// The one judge call a prompt may cost in `auto`: the kit's judge over the engine calls the register module
// injects. The text is masked and cut before it goes anywhere (the person's own model, or TypeSafe Jev when
// they opted in).
import type { RouteClass } from '../types'
import { judge } from './kit/judge'
import type { JudgeIo } from './kit/judge'
import { CLASSES, classOf, JUDGE_INSTRUCTIONS, JUDGE_TEXT_MAX } from './route'
import { redact } from './turns'

// null: no judgment (the call failed, timed out or named no class); the turn then keeps the person's effort.
export async function classify(io: JudgeIo, text: string): Promise<RouteClass | null> {
  const masked = redact([...text].slice(0, JUDGE_TEXT_MAX).join(''))
  const answer = await judge({ ...io, redact }, { text: masked, labels: CLASSES, instructions: JUDGE_INSTRUCTIONS })

  return classOf(answer?.label)
}

files.hooks/kit/home.tsx:
// MODZ kit — the way back to the hub from a mod's pane (DESIGN.md §9). While the hub runs it keeps
// `{ plugin: 'modz', key: 'isOn' }` true; a pane then draws `HomeButton` first, and its press writes the mod's
// own `{ plugin: '<mod>', key: 'home' }` value (`{ at }`). The hub hears it, comes forward, and opens again if
// it was closed, so the person always has a way back, even with one pane left and no tab to click.

// The resolved element table of the surface that draws the pane.
type Table = Record<string, any>

export const HOME_LABEL = '← MODZ'

export function HomeButton(ui: Table, onPress: () => void) {
  const { Box, Button } = ui

  return (
    <Box key="modz-home-row" flexDirection="row">
      <Button key="modz-home" label={HOME_LABEL} variant="secondary" onPress={onPress} />
    </Box>
  )
}

// The pane's tree with the way back above it; null while the hub is off draws the pane as it is.
export function withHome<T>(ui: Table, tree: T, onHome: (() => void) | null) {
  if (onHome === null) return tree
  const { Box } = ui

  return (
    <Box flexDirection="column" rowGap={1}>
      {HomeButton(ui, onHome)}
      {tree}
    </Box>
  )
}

